185:         /// <summary>
186:         /// 启动点胶线程
187:         /// </summary>
188:         /// <returns>结果</returns>
189:         public bool Start()
190:         {
191:             if (this.DispenseTask == null || this.DispenseTask.Status != TaskStatus.Running)
192:             {
193:                 // MachineStateModel.GetInstance().MachineState = Galaxy2.Machine.Enums.MachineStateEnum.Working;
194: 
195:                 this.DispenseTask = Task.Factory.StartNew(
196:                     () =>
197:                         {
198:                             CommonUtil.SetCurrentThreadName("点胶工作线程");
199:                             this.DoWork();
200:                         },
201:                     CancellationToken.None,
202:                     TaskCreationOptions.LongRunning,
203:                     TaskScheduler.Default);
204:             }
205: 
206:             return true;
207:         }
