123:                 return false; 
124:             }
125: 
126:             // 先判断设备状态，如果设备状态为停止，则不用判断信号量了
127:             do
128:             {
129:                 if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
130:                 {
131:                     return false;
132:                 }
133: 
134:                 Thread.Sleep(5);
135:             }
136:             while (!this.signalEvent.WaitOne(this.recycleTime));
137: 
138:             // 唐鹏添加
139:             if (this.resetMode == EventResetMode.AutoReset)
140:             {
141:                 this.State = SignalStateEnum.ReSet;
142:             }
143: 
144:             return true;
145:         }
146: 
147:         /// <summary>
148:         /// 等待信号  如果设备处于暂停状态，循环阻塞接收信号，如果设备停止 则返回false
149:         /// 所以在启动的时候 需要先设置设备状态，再启动线程
150:         /// </summary>
151:         /// <param name="outTime">超时时间</param>
152:         /// <returns>结果</returns>
153:         public bool Wait(int outTime)
154:         {
155:             bool res = WaitStart();
156: 
157:             // 等于false 则点了停止按钮，否则是从暂停恢复到工作状态
158:             if (res == false)
159:             {
160:                 return false;
161:             }
162: 
163:             if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
164:             {
165:                 return false;
166:             }
167: 
168:             return this.signalEvent.WaitOne(this.recycleTime);
169:         }
170: 
171:         /// <summary>
172:         /// 等待单步信号  
173:         /// </summary>
174:         /// <returns>等待成功</returns>
175:         public bool WaitSingleStep()
176:         {
177:             do
178:             {
179:                 // 如果不是单步模式，直接退出
180:                 if (MachineStateModel.GetInstance().IsSingleStepWork == false) 
181:                 {
182:                     return false;
183:                 }
184: 
185:                 Thread.Sleep(5);
186:             }
187:             while (!this.signalEvent.WaitOne(this.recycleTime));
188: 
189:             // 唐鹏添加
190:             if (this.resetMode == EventResetMode.AutoReset)
191:             {
192:                 this.State = SignalStateEnum.ReSet;
193:             }
194: 
195:             return true;
196:         }
197: 
198:         /// <summary>
199:         ///  等待开始  用于暂停时候的阻塞
200:         /// </summary>
201:         /// <returns>结果</returns>
202:         public static bool WaitStart()
203:         {
204:             // 维护模式 和调试模式 直接返回true
205:             //if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.MaintenceWork 
206:             //    || MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.Debug)
207:             //{
208:             //   // return true;               
209:             //}
210: 
211:             if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
212:             {
213:                 return false;
214:             }
215: 
216:             // 暂停状态 阻塞 
217:             while (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Pause)
218:             {
219:                 if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Stop)
220:                 {
221:                     return false;
222:                 }
223: 
224:                 Thread.Sleep(20);
225:             }
226: 
227:             return true;
228:         }

