371:         public ExcuteResult MatterHeightMeasurePoints(BaseMatter baseEntity, bool closeCy = false)
372:         {
373:             // 没有定位点直接返回
374:             if (baseEntity.Config.HeightMeasurementPoints.Count == 0)
375:             {
376:                 return ExcuteResult.Success;
377:             }
378: 
379:             // 没有测高功能没有开启，直接返回
380:             if (!baseEntity.Config.MeasureHeightInSystem1)
381:             {
382:                 return ExcuteResult.Success;
383:             }
384: 
385:             LogHelper.Post(Level.Info, "点胶测高开始", LogCategory.Dispense);
386: 
387:             // 结果的集合
388:             List<double> resultList = new List<double>();
389: 
390:             foreach (AKRSPoint3D pos in baseEntity.Config.HeightMeasurementPoints)
391:             {
392:                 // 单步工作
393:                 if (!System1Domain.GetInstance().WaitSingleStep())
394:                 {
395:                     return ExcuteResult.Abort;
396:                 }
397: 
398:                 // 计算G0坐标
399:                 AKRSPoint3D g0Pos = baseEntity.CoordinateSystem.SelfPosToG0(pos);
400: 
401:                 double addDistance = MachineHardwareConfiguration.GetInstance().IsSystem1ConfigLaserMh
402:                                ? 0
403:                                : DispenseDevicePara.GetInstance().DispenseModulePara.MeasureHeightDistance;
404: 
405:                 // 实际测高位置计算
406:                 AKRSPoint3D measHeightPos = new AKRSPoint3D(g0Pos.X, g0Pos.Y, g0Pos.Z + addDistance);
407: 
408:             RetryCommand:
409: 
410:                 // 执行测高
411:                 (ExcuteResult excuteResult, double height) result =
412:                     this.DispenseMeasureHeightController.DispenserHeightMeasurementG0(
413:                         System1MeasHeightToolEnum.HeightSensor,
414:                         measHeightPos,
415:                         double.NaN,
416:                         double.NaN,
417:                         closeCy);
418: 
419:                 double height = baseEntity.CoordinateSystem.G0PosToSelf(new AKRSPoint3D(0, 0, result.height)).Z;
420: 
421:                 resultList.Add(height);
422: 
423:                 // 高度预警
424:                 if (result.excuteResult != ExcuteResult.Success 
425:                     || Math.Abs(result.height - g0Pos.Z) > DispenseDevicePara.GetInstance().DispenseModulePara.MeasureHeightAlarmDistance
426:                     || double.IsNaN(result.height))
427:                 {
428:                     DialogResult dialogResult = AKRSMessageBoxExt.Show(
429:                         $"测高偏差数值为{height - g0Pos.Z}mm，超出设置阈值{DispenseDevicePara.GetInstance().DispenseModulePara.MeasureHeightAlarmDistance}\r\n"
430:                         + $"请选择如何处理",
431:                         "测高高度过大报警",
432:                         new string[] { "重试", "跳过", "终止" },
433:                         new DialogResult[] { DialogResult.Retry, DialogResult.Ignore, DialogResult.Abort },
434:                         AlarmLevel.FirstLevel);
435: 
436:                     switch (dialogResult)
437:                     {
438:                         case DialogResult.Retry:
439:                             goto RetryCommand;
440:                         case DialogResult.Ignore:
441:                             baseEntity.SetMatterDisable();
442:                             return ExcuteResult.Success;
443:                         case DialogResult.Abort:
444:                             return ExcuteResult.Exception;
445:                     }
446:                 }
447: 
448:             }
449: 
450:             // 计算测高点的
451:             double averageHeight = resultList.Average();
452: 
453:             // 计算之前的高度
454:             double averageHeightOld = baseEntity.Config.HeightMeasurementPoints.Select(it => it.Z).Average();
455: 
456:             // 现在的高度减去之前的高度
457:             double addHieght = averageHeight - averageHeightOld;
458: 
459:             // 保存结果
460:             baseEntity.BaseInfo.MeasureHeightResult = addHieght;
461: 
462:             if (double.IsNaN(addHieght))
463:             {
464:                 throw new Exception("测高结果为NaN，请检查激光传感器是否存在问题");
465:             }
466: 
467:             // 更新差值
468:             baseEntity.CoordinateSystem.Distance.Z += addHieght;
469: 
470:             LogHelper.Post(Level.Info, $"点胶测高结束,高度为{averageHeight}", LogCategory.Dispense);
471: 
472:             baseEntity.BaseInfo.IsMeasureHeight = true;
473: 
474:             return ExcuteResult.Success;

