600:                     System2RunTimeProvider.RecordTime("系统1ID识别", $"{p1VisionPosInG01}身份识别失败，手动识别成功");
601:                     codeResult = (CodeResult)result.matchResult;
602:                 }
603:                 else if (result.dialog == DialogResult.Ignore)
604:                 {
605:                     System2RunTimeProvider.RecordTime("系统1ID识别", $"{p1VisionPosInG01}身份识别失败，手动识别失败");
606:                     baseEntity.SetMatterDisable();
607:                     return ExcuteResult.Success;
608:                 }
609:                 else if (result.dialog == DialogResult.Abort)
610:                 {
611:                     System2RunTimeProvider.RecordTime("系统1ID识别", $"{p1VisionPosInG01}身份识别失败，停止");
612:                     Machine.GetInstance().Stop();
613:                     return ExcuteResult.Abort;
614:                 }
615:                 else
616:                 {
617:                     return ExcuteResult.Abort;
618:                 }
619:             }
620: 
621:             #endregion
622: 
